#include <bits/stdc++.h>

using namespace std;

#define loop_var(i, start, end) for(int i=start; i<end; i++)
#define vec_add push_back
#define range_iterate(a) a.begin(), a.end()
#define get_len(a) ((int)a.size())
#define reset_mem(a, b) memset(a, b, sizeof(a))
#define first_index first
#define second_index second

typedef long long ll;

typedef int flow_type;
typedef int cost_type;
const flow_type INF=1e9;
struct FlowNetwork {
	int total_nodes;
	vector<cost_type> dist, potential; vector<flow_type> flow_now; vector<int> prev_edge, prev_node;
	priority_queue<pair<cost_type, int>, vector<pair<cost_type, int>>, greater<pair<cost_type, int>>> pq;
	struct Edge {int to, rev; flow_type flow, cap; cost_type cost;};
	vector<vector<Edge>> adj;
	FlowNetwork(int n):total_nodes(n), dist(n), flow_now(n), prev_edge(n), prev_node(n), potential(n), adj(n){}
	void add_edge(int s, int t, flow_type cap, cost_type cst) {
		adj[s].push_back({t, (int)adj[t].size(), 0, cap, cst});
		adj[t].push_back({s, (int)adj[s].size()-1, 0, 0, -cst});
	}
	pair<flow_type, cost_type> min_cost_max_flow(int s, int t) {
		flow_type total_flow=0; cost_type total_cost=0;
		while(true){
			pq.push({0, s});
			reset_mem(dist, INF);
			dist[s]=0; flow_now[s]=INF;
			while(!pq.empty()){
				auto p=pq.top(); pq.pop();
				cost_type d=p.first_index; int u=p.second_index;
				if(d!=dist[u]) continue;
				for(int i=0; i<(int)adj[u].size(); i++){
					auto &e=adj[u][i];
					int v=e.to;
					if(e.cap<=e.flow) continue;
					cost_type new_d=dist[u]+e.cost+potential[u]-potential[v];
					if(dist[v]>new_d){
						dist[v]=new_d;
						pq.push({new_d, v});
						prev_node[v]=u; prev_edge[v]=i;
						flow_now[v]=min(flow_now[u], e.cap-e.flow);
					}
				}
			}
			if(dist[t]==INF) break;
			for_var(i,0,total_nodes) potential[i]+=dist[i];
			flow_type delta=min(flow_now[t], (flow_type)(INF - total_flow));
			total_flow+=delta;
			for(int v=t; v!=s; v=prev_node[v]){
				auto &e=adj[prev_node[v]][prev_edge[v]];
				e.flow+=delta; adj[v][e.rev].flow-=delta;
				total_cost+=delta*e.cost;
			}
		}
		return {total_flow, total_cost};
	}
};

int T=150;

int main() {
  int n, m, k, c, d; cin >> n >> m >> k >> c >> d;
  int N = n*T;
  FlowNetwork fn(N + 2);
  loop_var(i, 0, n) loop_var(j, 0, T - 1) {
    fn.add_edge(i * T + j, i * T + j + 1, INF, c);
