    int x, y; cin >> x >> y; x--, y--;
    loop_var(j, 0, T - 1) {
      int cur=1;
      loop_var(_, 0, k) {
        fn.add_edge(x * T + j, y * T + j + 1, 1, cur * d + c);
        fn.add_edge(y * T + j, x * T + j + 1, 1, cur * d + c);
        cur+=2;
      }
    }
  }
  auto flow_result=fn.min_cost_max_flow(N, N + 1);
  assert(flow_result.first_elem==k);
  cout << flow_result.second_elem << endl;
  return 0;
}
