import java.util.*;

public class Main {
    static class Edge {
        int to, rev;
        long flow, cap;
        long cost;
        public Edge(int to, int rev, long flow, long cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.flow = flow;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class FlowNetwork {
        int totalNodes;
        long[] dist, potential;
        long[] flowNow;
        int[] prevEdge, prevNode;
        PriorityQueue<Pair> pq;
        List<List<Edge>> adj;
        static final long INF = (long)1e9;

        public FlowNetwork(int n) {
            totalNodes = n;
            dist = new long[n];
            potential = new long[n];
            flowNow = new long[n];
            prevEdge = new int[n];
            prevNode = new int[n];
            pq = new PriorityQueue<>(Comparator.comparingLong(p -> p.first));
            adj = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                adj.add(new ArrayList<>());
            }
        }

        public void addEdge(int s, int t, long cap, long cst) {
            adj.get(s).add(new Edge(t, adj.get(t).size(), 0, cap, cst));
            adj.get(t).add(new Edge(s, adj.get(s).size() - 1, 0, 0, -cst));
        }

        public Pair minCostMaxFlow(int s, int t) {
            long totalFlow = 0;
            long totalCost = 0;
            while (true) {
                pq.clear();
                Arrays.fill(dist, INF);
                dist[s] = 0;
                flowNow[s] = INF;
                pq.offer(new Pair(0, s));
                while (!pq.isEmpty()) {
                    Pair p = pq.poll();
                    long d = p.first;
                    int u = p.second;
                    if (d != dist[u]) continue;
                    for (int i = 0; i < adj.get(u).size(); i++) {
                        Edge e = adj.get(u).get(i);
                        int v = e.to;
                        if (e.cap <= e.flow) continue;
                        long newD = dist[u] + e.cost + potential[u] - potential[v];
                        if (dist[v] > newD) {
                            dist[v] = newD;
                            pq.offer(new Pair(newD, v));
                            prevNode[v] = u;
                            prevEdge[v] = i;
                            flowNow[v] = Math.min(flowNow[u], e.cap - e.flow);
                        }
                    }
                }
                if (dist[t] == INF) break;
                for (int i = 0; i < totalNodes; i++) {
                    potential[i] += dist[i];
                }
                long delta = Math.min(flowNow[t], INF - totalFlow);
                totalFlow += delta;
                for (int v = t; v != s; v = prevNode[v]) {
                    Edge e = adj.get(prevNode[v]).get(prevEdge[v]);
                    e.flow += delta;
                    adj.get(v).get(e.rev).flow -= delta;
                    totalCost += delta * e.cost;
                }
            }
            return new Pair(totalFlow, totalCost);
        }
    }

    static class Pair {
        long first;
        int second;
        public Pair(long first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();
        int T = 150;
        int N = n * T;
        FlowNetwork fn = new FlowNetwork(N + 2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < T - 1; j++) {
                fn.addEdge(i * T + j, i * T + j + 1, FlowNetwork.INF, c);
            }
        }
        for (int i = 0; i < T; i++) {
            fn.addEdge(i, N + 1, FlowNetwork.INF, 0);
        }
        for (int i = 0; i < k; i++) {
            int x = sc.nextInt() - 1;
            fn.addEdge(N, x * T, 1, 0);
        }
        for (int i = 0; i < m; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            for (int j = 0; j < T - 1; j++) {
                int cur = 1;
                for (int _ = 0; _ < k; _++) {
                    fn.addEdge(x * T + j, y * T + j + 1, 1, cur * d + c);
                    fn.addEdge(y * T + j, x * T + j + 1, 1, cur * d + c);
                    cur += 2;
                }
            }
        }
        Pair flowResult = fn.minCostMaxFlow(N, N + 1);
        if (flowResult.first != k) {
            throw new AssertionError();
        }
        System.out.println(flowResult.second);
        sc.close();
    }
}

